INSERT INTO benutzer (id, timestamperstellt, timestampmutiert, usererstellt, usermutiert, version, email, keycloakid, nachname, vorname, lastusedip, lastusedsessionid, lastusedsessiontimestamp, oidcissuer, benutzeraktivstatus, fachrollen) VALUES ('b7611438-6764-4e1f-8f51-fc4eda7af54e', '2026-03-23 09:09:00.118393', '2026-03-23 09:09:00.202890', '11111111-1111-1111-1111-111111111111', '11111111-1111-1111-1111-111111111111', 0, 'schularzt-dummy-organisation@dvbern.ch', null, 'WIN', 'Verantwortlicher Schularzt', null, null, null, null, 'AKTIV', 'SCHULAERZTIN');
INSERT INTO organisation (id, timestamperstellt, timestampmutiert, usererstellt, usermutiert, version, verantwortlicherarzt_id) VALUES ('08831a31-a62b-4c81-adfc-3f3bcb3a1fee', '2026-03-23 09:09:00.118393', '2026-03-23 09:09:00.202890', '11111111-1111-1111-1111-111111111111', '11111111-1111-1111-1111-111111111111', 0, 'b7611438-6764-4e1f-8f51-fc4eda7af54e');
INSERT INTO organisationrollen (id, timestamperstellt, timestampmutiert, usererstellt, usermutiert, version, organisation_id, benutzer_id, fachrollen) SELECT uuid_generate_v4(), current_timestamp, current_timestamp, '11111111-1111-1111-1111-111111111111', '11111111-1111-1111-1111-111111111111', 0, '08831a31-a62b-4c81-adfc-3f3bcb3a1fee', id, fachrollen FROM benutzer WHERE id != 'b7611438-6764-4e1f-8f51-fc4eda7af54e' AND fachrollen NOT LIKE '%SUPPORT%' AND fachrollen NOT LIKE '%SYSTEM_ADMIN%';
INSERT INTO systemrollen (id, timestamperstellt, timestampmutiert, usererstellt, usermutiert, version, benutzer_id, fachrollen) SELECT uuid_generate_v4(), current_timestamp, current_timestamp, '11111111-1111-1111-1111-111111111111', '11111111-1111-1111-1111-111111111111', 0, id, fachrollen FROM benutzer WHERE fachrollen LIKE '%SUPPORT%' OR fachrollen LIKE '%SYSTEM_ADMIN%';
